mapper.select:
SELECT

FROM notification_record
WHERE winning_record_id = #{winningRecordId}
  AND channel = #{channel}
FOR SHARE

mapper.update:
UPDATE notification_record
SET status = 1,
    processing_token = #{processingToken},
    processing_time = #{processingTime},
    next_retry_time = NULL,
    update_time = #{processingTime}
WHERE id = #{id}
  AND status = 0
  AND next_retry_time IS NOT NULL
  AND next_retry_time <= #{processingTime}

UPDATE notification_record
SET processing_time = #{processingTime},
    update_time = #{processingTime}
WHERE id = #{id}
  AND status = 1
  AND processing_token = #{processingToken}
  AND retry_count = #{expectedRetryCount}

UPDATE notification_record
SET status = #{targetStatus},
    retry_count = retry_count + 1,
    next_retry_time = #{nextRetryTime},
    processing_token = NULL,
    processing_time = NULL,
    last_error = #{lastError},
    update_time = #{updatedTime}
WHERE id = #{id}
  AND status = 1
  AND processing_token = #{processingToken}
  AND retry_count = #{expectedRetryCount}
  AND #{targetStatus} IN (0, 3)

